        System.out.println("inOrder:     " + tree);
        System.out.println("size:        " + tree.size());
        System.out.println("isEmpty:     " + tree.isEmpty());
        System.out.println("contains 25: " + tree.contains(25));
        System.out.println("contains 99: " + tree.contains(99));
